contract InvMutTest {
    C c;
    constructor() payable { c = new C{value: 10 ether}(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint salt) public payable {
        uint v1 = c.pastBlockTime(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;
        uint v2 = c.pastBlockTime(); if (__ESBMC_reverted()) return;
        assert(v1 == v2 && address(c).balance == balBefore && v2 <= block.timestamp + salt * 0);
    }
    receive() external payable {}
}

