pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Roulette c;

    function setUp() public {
        vm.deal(address(this), 10 ether);
        c = new Roulette{value: 10 ether}();
    }

    function _run(uint256 salt) internal {
        uint256 v1;
        try c.pastBlockTime() returns (uint256 __r) { v1 = __r; } catch { return; }
        uint balBefore = address(c).balance;
        uint256 v2;
        try c.pastBlockTime() returns (uint256 __r) { v2 = __r; } catch { return; }
        assertTrue(v1 == v2 && address(c).balance == balBefore && v2 <= block.timestamp + salt * 0);
    }

    function testFuzz_run(uint256 salt) public {
        _run(salt);
    }

    receive() external payable {}
}
